<?php $s=$settings??[]; ?>
<form class="surface product-section" method="post" action="<?= e(url('/sales/settings')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><div class="product-fields"><label>Shop legal name *<input name="legal_name" required maxlength="150" value="<?= e($s['legal_name']??$shopName) ?>"></label><label>Registration type *<select name="registration_type"><?php foreach(['unregistered'=>'Unregistered business','regular'=>'Regular GST registered','composition'=>'Composition taxpayer'] as $v=>$label): ?><option value="<?= e($v) ?>" <?= ($s['registration_type']??'')===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label class="wide">Shop address *<textarea name="address" maxlength="500" required rows="2"><?= e($s['address']??'') ?></textarea></label><label>State *<select name="state_code" required><option value="">Choose state</option><?php foreach($states as $code=>$name): ?><option value="<?= e((string)$code) ?>" <?= ($s['state_code']??'')===(string)$code?'selected':'' ?>><?= e($name) ?> (<?= e((string)$code) ?>)</option><?php endforeach; ?></select></label><label>GSTIN (registered businesses)<input name="gstin" maxlength="15" value="<?= e($s['gstin']??'') ?>"></label><label>Selling prices<select name="price_mode"><option value="inclusive">Tax inclusive</option><option value="exclusive" <?= ($s['price_mode']??'')==='exclusive'?'selected':'' ?>>Tax exclusive</option></select></label><label>Default tax classification<select name="default_tax_rate_id"><option value="">Require product classification</option><?php foreach($rates as $rate): ?><option value="<?= (int)$rate['id'] ?>" <?= ($s['default_tax_rate_id']??'')==$rate['id']?'selected':'' ?>><?= e($rate['name']) ?> · <?= e($rate['rate']) ?>%</option><?php endforeach; ?></select></label><label>Labour tax classification<select name="labour_tax_rate_id"><option value="">Not configured</option><?php foreach($rates as $rate): ?><option value="<?= (int)$rate['id'] ?>" <?= ($s['labour_tax_rate_id']??'')==$rate['id']?'selected':'' ?>><?= e($rate['name']) ?> · <?= e($rate['rate']) ?>%</option><?php endforeach; ?></select><small>Required for labour on regular GST bills. No product rate is assumed.</small></label><label>Labour SAC code<input name="labour_sac_code" maxlength="20" value="<?= e($s['labour_sac_code']??'') ?>"></label><label>Invoice series prefix *<input name="invoice_prefix" required maxlength="4" pattern="[A-Za-z0-9]{1,4}" value="<?= e($s['invoice_prefix']??'INV') ?>"><small>Prefix / financial year / six-digit sequence</small></label><label class="check-label"><input type="checkbox" name="require_hsn" <?= !empty($s['require_hsn'])?'checked':'' ?>> Require HSN / SAC on GST invoices</label><label class="wide">Invoice footer / shop message<textarea name="footer" rows="2" maxlength="300"><?= e($s['footer']??'') ?></textarea></label></div><button class="button button-primary">Save settings</button></form>
<section class="surface product-section sales-tax-rates"><h2>Tax classifications</h2><p class="subtle-text">Enter the rates applicable to your goods. Product classifications take priority over the default.</p><ul><?php foreach($rates as $rate): ?><li><?= e($rate['name']) ?> · <?= e($rate['rate']) ?>%</li><?php endforeach; ?></ul><form method="post" action="<?= e(url('/sales/settings')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="tax_rate"><div class="product-fields"><label>Name<input name="name" maxlength="80" required></label><label>Rate (%)<input name="rate" type="number" min="0" max="100" step="0.01" required></label></div><button class="button">Add classification</button></form></section>
